using DonationHub.Domain.Common;

namespace DonationHub.Domain.Donations;

public enum PaymentAttemptStatus { Created, Succeeded, Failed, Expired }

public sealed class PaymentAttempt : Entity
{
    private PaymentAttempt() { }   // EF Core
    private PaymentAttempt(Guid id) : base(id) { }

    public Guid DonationId { get; private set; }
    public string StripeCheckoutSessionId { get; private set; } = default!;
    public string? StripePaymentIntentId { get; private set; }
    public decimal Amount { get; private set; }
    public PaymentAttemptStatus Status { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime UpdatedAt { get; private set; }
    public string? FailureCode { get; private set; }

    public bool IsOpen => Status == PaymentAttemptStatus.Created;

    // id يُولَّد قبل استدعاء Stripe حتى يوضع في metadata الجلسة
    public static PaymentAttempt Create(Guid id, Donation donation, string checkoutSessionId, DateTime utcNow)
    {
        if (donation.Status != DonationStatus.Pending)
            throw new DomainException("Donation.InvalidState", "Only a pending donation can start a payment.");
        if (string.IsNullOrWhiteSpace(checkoutSessionId))
            throw new DomainException("Validation.Failed", "Checkout session id is required.");

        return new PaymentAttempt(id)
        {
            DonationId = donation.Id,
            StripeCheckoutSessionId = checkoutSessionId,
            Amount = donation.Amount,   // من حالة الخادم، لا من العميل
            Status = PaymentAttemptStatus.Created,
            CreatedAt = utcNow,
            UpdatedAt = utcNow
        };
    }

    public void MarkSucceeded(string? paymentIntentId, DateTime utcNow)
    {
        // Checkout يسمح بإعادة المحاولة ببطاقة أخرى داخل نفس الجلسة بعد payment_failed،
        // لذلك Failed -> Succeeded مسموح للمحاولة (المال وصل فعلًا ويجب تسجيله)
        if (Status is not (PaymentAttemptStatus.Created or PaymentAttemptStatus.Failed))
            throw new DomainException("Donation.InvalidState", $"Payment attempt is already {Status}.");

        Status = PaymentAttemptStatus.Succeeded;
        StripePaymentIntentId = paymentIntentId ?? StripePaymentIntentId;
        FailureCode = null;
        UpdatedAt = utcNow;
    }

    public void MarkFailed(string failureCode, string? paymentIntentId, DateTime utcNow)
    {
        EnsureOpen();
        Status = PaymentAttemptStatus.Failed;
        FailureCode = failureCode;
        StripePaymentIntentId = paymentIntentId ?? StripePaymentIntentId;
        UpdatedAt = utcNow;
    }

    public void MarkExpired(DateTime utcNow)
    {
        EnsureOpen();
        Status = PaymentAttemptStatus.Expired;
        UpdatedAt = utcNow;
    }

    private void EnsureOpen()
    {
        if (!IsOpen)
            throw new DomainException("Donation.InvalidState", $"Payment attempt is already {Status}.");
    }
}

namespace DonationHub.Application.Features.Payments.Common;

public static class MinorUnits
{
    // عملات بلا كسور في Stripe (قائمة مختصرة — راجع توثيق Stripe قبل إضافة عملة جديدة)
    private static readonly HashSet<string> ZeroDecimal =
        new(StringComparer.OrdinalIgnoreCase) { "JPY", "KRW", "VND", "CLP", "XAF", "XOF" };

    public static long FromAmount(decimal amount, string currency)
    {
        var factor = ZeroDecimal.Contains(currency) ? 1m : 100m;   // USD, EUR, EGP: 100
        var minor = decimal.Round(amount * factor, 0, MidpointRounding.AwayFromZero);
        return checked((long)minor);
    }

    public static decimal ToAmount(long minor, string currency) =>
        ZeroDecimal.Contains(currency) ? minor : minor / 100m;
}

