namespace DonationHub.Infrastructure.Options;

public sealed class StripeOptions
{
    public const string SectionName = "Stripe";

    // PAY-10: مفاتيح test mode فقط
    [Required]
    [RegularExpression("^sk_test_[A-Za-z0-9_]+$", ErrorMessage = "Stripe:SecretKey must be a test-mode key (sk_test_...).")]
    public string SecretKey { get; init; } = string.Empty;

    [Required]
    [RegularExpression("^whsec_[A-Za-z0-9_]+$", ErrorMessage = "Stripe:WebhookSecret must start with whsec_.")]
    public string WebhookSecret { get; init; } = string.Empty;

    [Required, StringLength(3, MinimumLength = 3)]
    public string Currency { get; init; } = "usd";

    [Required, Url] public string SuccessUrl { get; init; } = string.Empty;
    [Required, Url] public string CancelUrl { get; init; } = string.Empty;

    // Stripe يشترط أن تنتهي الجلسة بعد 30 دقيقة على الأقل من إنشائها
    [Range(31, 1440)] public int SessionExpiryMinutes { get; init; } = 60;
}

