using Stripe.Checkout;

namespace DonationHub.Infrastructure.Payments;

internal sealed class StripePaymentGateway(
    IStripeClient stripeClient,
    IOptions<StripeOptions> options,
    TimeProvider timeProvider) : IPaymentGateway
{
    private readonly StripeOptions _options = options.Value;

    public string Currency => _options.Currency.ToLowerInvariant();

    public async Task<CheckoutSessionCreated> CreateCheckoutSessionAsync(
        CreateCheckoutSessionRequest request, CancellationToken ct)
    {
        var metadata = new Dictionary<string, string>
        {
            ["donationId"] = request.DonationId.ToString(),
            ["campaignId"] = request.CampaignId.ToString(),
            ["paymentAttemptId"] = request.PaymentAttemptId.ToString()
        };

        var sessionOptions = new SessionCreateOptions
        {
            Mode = "payment",
            ClientReferenceId = request.DonationId.ToString(),   // PAY-02
            Metadata = metadata,
            // payment_intent.payment_failed يحمل الـ PaymentIntent لا الجلسة، فننسخ الـ metadata إليه
            PaymentIntentData = new SessionPaymentIntentDataOptions { Metadata = metadata },
            LineItems =
            [
                new SessionLineItemOptions
                {
                    Quantity = 1,
                    PriceData = new SessionLineItemPriceDataOptions
                    {
                        Currency = Currency,
                        UnitAmount = request.AmountMinor,   // long بالسنتات
                        ProductData = new SessionLineItemPriceDataProductDataOptions
                        {
                            Name = request.CampaignTitle
                        }
                    }
                }
            ],
            SuccessUrl = _options.SuccessUrl,
            CancelUrl = _options.CancelUrl,
            ExpiresAt = timeProvider.GetUtcNow().UtcDateTime.AddMinutes(_options.SessionExpiryMinutes)
        };

        var service = new SessionService(stripeClient);
        var session = await service.CreateAsync(
            sessionOptions,
            new RequestOptions { IdempotencyKey = request.IdempotencyKey },  // إعادة إرسال آمنة لنفس المحاولة
            ct);

        return new CheckoutSessionCreated(session.Id, session.Url);
    }
}

