namespace DonationHub.Application.Features.Payments.CreateCheckoutSession;

public sealed record CreateCheckoutSessionCommand(Guid DonationId, Guid UserId)
    : IRequest<Result<CheckoutSessionResponse>>;

public sealed record CheckoutSessionResponse(
    Guid DonationId, Guid PaymentAttemptId, string SessionId, string CheckoutUrl);

internal sealed class CreateCheckoutSessionCommandHandler(
    IUnitOfWork uow,
    IPaymentGateway gateway,
    TimeProvider timeProvider,
    ILogger<CreateCheckoutSessionCommandHandler> logger)
    : IRequestHandler<CreateCheckoutSessionCommand, Result<CheckoutSessionResponse>>
{
    public async Task<Result<CheckoutSessionResponse>> Handle(CreateCheckoutSessionCommand command, CancellationToken ct)
    {
        var donation = await uow.Repository<Donation>().GetByIdAsync(command.DonationId, ct);
        if (donation is null || donation.DonorUserId != command.UserId)
            return DonationErrors.NotFound;   // لا نكشف وجود تبرع لغير صاحبه

        if (donation.Status != DonationStatus.Pending)
            return DonationErrors.InvalidState;   // 409

        var now = timeProvider.GetUtcNow().UtcDateTime;
        var campaign = await uow.Repository<Campaign>().GetByIdAsync(donation.CampaignId, ct);
        if (campaign is null || campaign.Status != CampaignStatus.Active || campaign.EndDate <= now)
            return CampaignErrors.NotActive;   // لا نفتح جلسة دفع لحملة انتهت

        var attemptId = Guid.NewGuid();
        var session = await gateway.CreateCheckoutSessionAsync(new CreateCheckoutSessionRequest(
            DonationId: donation.Id,
            CampaignId: campaign.Id,
            PaymentAttemptId: attemptId,
            CampaignTitle: campaign.TitleEn,
            AmountMinor: MinorUnits.FromAmount(donation.Amount, gateway.Currency),
            IdempotencyKey: $"checkout-{attemptId}"), ct);

        var attempt = PaymentAttempt.Create(attemptId, donation, session.SessionId, now);
        await uow.Repository<PaymentAttempt>().AddAsync(attempt, ct);
        await uow.SaveChangesAsync(ct);

        logger.LogInformation("Checkout session {SessionId} created for donation {DonationId} (attempt {AttemptId})",
            session.SessionId, donation.Id, attempt.Id);

        return new CheckoutSessionResponse(donation.Id, attempt.Id, session.SessionId, session.CheckoutUrl);
    }
}

