namespace DonationHub.Application.Features.Payments.GetPaymentStatus;

public sealed record GetPaymentStatusQuery(Guid DonationId, Guid UserId, bool IsAdmin)
    : IRequest<Result<PaymentStatusResponse>>;

public sealed record LatestAttemptResponse(
    Guid Id, PaymentAttemptStatus Status, string? FailureCode, DateTime CreatedAt, DateTime UpdatedAt);

public sealed record PaymentStatusResponse(
    Guid DonationId, DonationStatus DonationStatus, LatestAttemptResponse? LatestAttempt);

internal sealed class GetPaymentStatusQueryHandler(IReadDbContext read)
    : IRequestHandler<GetPaymentStatusQuery, Result<PaymentStatusResponse>>
{
    public async Task<Result<PaymentStatusResponse>> Handle(GetPaymentStatusQuery query, CancellationToken ct)
    {
        var donation = await read.Donations
            .Where(d => d.Id == query.DonationId && (query.IsAdmin || d.DonorUserId == query.UserId))
            .Select(d => new { d.Id, d.Status })
            .FirstOrDefaultAsync(ct);

        if (donation is null)
            return DonationErrors.NotFound;   // تبرع مستخدم آخر = 404

        var latest = await read.PaymentAttempts
            .Where(a => a.DonationId == donation.Id)
            .OrderByDescending(a => a.CreatedAt)
            .Select(a => new LatestAttemptResponse(a.Id, a.Status, a.FailureCode, a.CreatedAt, a.UpdatedAt))
            .FirstOrDefaultAsync(ct);

        return new PaymentStatusResponse(donation.Id, donation.Status, latest);
    }
}

