namespace DonationHub.Api.Controllers;

[ApiController]
[ApiVersion("1.0")]
[Route("api/v{version:apiVersion}/payments")]
public sealed class PaymentsController(ISender sender) : ApiControllerBase
{
    // PAY-04: مجهول (التوقيع هو المصادقة) ومستثنى من الـ rate limiting (SRS §6.4)
    [HttpPost("webhook")]
    [AllowAnonymous]
    [DisableRateLimiting]
    [ApiExplorerSettings(IgnoreApi = true)]   // لا داعي لظهوره في Scalar
    public async Task<IActionResult> Webhook(CancellationToken ct)
    {
        // لا [FromBody]: نحتاج النص كما وقّعه Stripe حرفيًا
        using var reader = new StreamReader(Request.Body, Encoding.UTF8);
        var payload = await reader.ReadToEndAsync(ct);
        var signature = Request.Headers["Stripe-Signature"].ToString();

        var result = await sender.Send(new ProcessStripeWebhookCommand(payload, signature), ct);
        return result.IsSuccess ? Ok() : ProblemFrom(result.Error);   // 400 Payment.InvalidSignature
    }
}

