namespace DonationHub.Infrastructure.Payments;

internal sealed class StripeWebhookVerifier(
    IOptions<StripeOptions> options,
    ILogger<StripeWebhookVerifier> logger) : IPaymentWebhookVerifier
{
    public Result<PaymentWebhookEvent> Verify(string payload, string signatureHeader)
    {
        if (string.IsNullOrWhiteSpace(signatureHeader))
            return PaymentErrors.InvalidSignature;

        Event stripeEvent;
        try
        {
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                signatureHeader,
                options.Value.WebhookSecret,
                throwOnApiVersionMismatch: false);
        }
        catch (StripeException ex)
        {
            // لا نسجّل الـ payload ولا السر — السبب فقط
            logger.LogWarning("Rejected Stripe webhook: {Reason}", ex.Message);
            return PaymentErrors.InvalidSignature;
        }

        PaymentWebhookEvent result = stripeEvent.Type switch
        {
            EventTypes.CheckoutSessionCompleted when stripeEvent.Data.Object is Session completed
                => FromSession(stripeEvent, completed, PaymentEventKind.CheckoutCompleted),
            EventTypes.CheckoutSessionExpired when stripeEvent.Data.Object is Session expired
                => FromSession(stripeEvent, expired, PaymentEventKind.CheckoutExpired),
            EventTypes.PaymentIntentPaymentFailed when stripeEvent.Data.Object is PaymentIntent intent
                => new PaymentWebhookEvent(
                    stripeEvent.Id, stripeEvent.Type, PaymentEventKind.PaymentFailed,
                    PaymentIntentId: intent.Id,
                    FailureCode: intent.LastPaymentError?.DeclineCode ?? intent.LastPaymentError?.Code ?? "payment_failed",
                    PaymentAttemptId: intent.Metadata?.GetValueOrDefault("paymentAttemptId")),
            _ => new PaymentWebhookEvent(stripeEvent.Id, stripeEvent.Type, PaymentEventKind.Unhandled)
        };

        return result;
    }

    private static PaymentWebhookEvent FromSession(Event stripeEvent, Session session, PaymentEventKind kind) =>
        new(stripeEvent.Id, stripeEvent.Type, kind,
            CheckoutSessionId: session.Id,
            ClientReferenceId: session.ClientReferenceId,
            PaymentIntentId: session.PaymentIntentId,
            PaymentStatus: session.PaymentStatus,   // "paid" / "unpaid" / "no_payment_required"
            AmountTotalMinor: session.AmountTotal,
            Currency: session.Currency,
            PaymentAttemptId: session.Metadata?.GetValueOrDefault("paymentAttemptId"));
}

