// Infrastructure/Payments/PaymentsRepository.cs
internal sealed class PaymentsRepository(AppDbContext db) : IPaymentsRepository
{
    public Task<PaymentAttempt?> GetAttemptBySessionIdAsync(string sessionId, CancellationToken ct) =>
        db.PaymentAttempts.FirstOrDefaultAsync(a => a.StripeCheckoutSessionId == sessionId, ct);

    public Task<PaymentAttempt?> GetAttemptByPaymentIntentIdAsync(string paymentIntentId, CancellationToken ct) =>
        db.PaymentAttempts.FirstOrDefaultAsync(a => a.StripePaymentIntentId == paymentIntentId, ct);

    public Task<bool> HasOtherOpenAttemptsAsync(Guid donationId, Guid exceptAttemptId, CancellationToken ct) =>
        db.PaymentAttempts.AnyAsync(a => a.DonationId == donationId
                                      && a.Id != exceptAttemptId
                                      && a.Status == PaymentAttemptStatus.Created, ct);

    // يسأل قاعدة البيانات لا الـ change tracker
    public Task<bool> IsEventProcessedAsync(string eventId, CancellationToken ct) =>
        db.ProcessedStripeEvents.AsNoTracking().AnyAsync(e => e.EventId == eventId, ct);

    public void AddProcessedEvent(ProcessedStripeEvent processedEvent) =>
        db.ProcessedStripeEvents.Add(processedEvent);
}

using DonationHub.Application.Abstractions;
using DonationHub.Application.Common.Caching;
using DonationHub.Application.Features.Payments.Common;
using DonationHub.Domain.Campaigns;
using DonationHub.Domain.Common;
using DonationHub.Domain.Donations;
using MediatR;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace DonationHub.Application.Features.Payments.ProcessStripeWebhook;

public sealed record ProcessStripeWebhookCommand(string Payload, string SignatureHeader) : IRequest<Result>;

internal sealed class ProcessStripeWebhookCommandHandler(
    IPaymentWebhookVerifier verifier,
    IPaymentsRepository payments,
    IUnitOfWork uow,
    IReceiptNumberGenerator receiptNumbers,
    IBackgroundJobScheduler jobs,
    ICacheService cache,
    IPaymentGateway gateway,
    TimeProvider timeProvider,
    ILogger<ProcessStripeWebhookCommandHandler> logger)
    : IRequestHandler<ProcessStripeWebhookCommand, Result>
{
    private const int MaxAttempts = 3;   // DON-08: كما في DonationSuccessFlow
    private string? _receiptNumber;   // رقم إيصال واحد عبر المحاولات

    private sealed record AfterCommit(
        Guid? ReceiptForDonation = null, Guid? GoalReachedCampaign = null, Guid? ChangedCampaign = null)
    {
        public static readonly AfterCommit Nothing = new();
    }

    public async Task<Result> Handle(ProcessStripeWebhookCommand command, CancellationToken ct)
    {
        var verified = verifier.Verify(command.Payload, command.SignatureHeader);
        if (verified.IsFailure)
            return verified.Error;   // 400 — لم نلمس قاعدة البيانات

        var evt = verified.Value;

        // PAY-06: التسليم at-least-once — الحدث المعالَج سابقًا يُقرّ به فقط
        if (await payments.IsEventProcessedAsync(evt.EventId, ct))
        {
            logger.LogInformation("Duplicate Stripe event {EventId} ({EventType}) ignored", evt.EventId, evt.Type);
            return Result.Success();
        }

        var now = timeProvider.GetUtcNow().UtcDateTime;
        for (var attempt = 1; ; attempt++)
        {
            var afterCommit = evt.Kind switch
            {
                PaymentEventKind.CheckoutCompleted => await HandleCompletedAsync(evt, now, ct),
                PaymentEventKind.CheckoutExpired => await HandleExpiredAsync(evt, now, ct),
                PaymentEventKind.PaymentFailed => await HandleFailedAsync(evt, now, ct),
                _ => LogUnhandled(evt)
            };

            payments.AddProcessedEvent(ProcessedStripeEvent.Create(evt.EventId, evt.Type, now));

            try
            {
                await uow.SaveChangesAsync(ct);   // معاملة واحدة: تغييرات الحدث + سجل الحدث
            }
            catch (DbUpdateConcurrencyException) when (attempt < MaxAttempts)
            {
                // DON-08: تبرع آخر للحملة حُفظ قبلنا (RowVersion) — لم يُحفظ شيء؛ نعيد بقيم حديثة
                uow.ClearChangeTracker();
                continue;
            }
            catch (DbUpdateException)
            {
                // تسليمان متزامنان لنفس الحدث: الآخر حفظ قبلنا — هذا تكرار وليس خطأ
                if (await payments.IsEventProcessedAsync(evt.EventId, CancellationToken.None))
                {
                    logger.LogInformation("Stripe event {EventId} was processed concurrently", evt.EventId);
                    return Result.Success();
                }
                throw;   // استنفدنا المحاولات: 500 فيعيد Stripe الإرسال
            }

            // PAY-08: بعد الـ commit فقط — لا إيصال لتبرع تراجعت معاملته
            if (afterCommit.ReceiptForDonation is Guid donationId)
                jobs.EnqueueDonationReceipt(donationId);
            if (afterCommit.GoalReachedCampaign is Guid campaignId)
                jobs.EnqueueGoalReachedEmail(campaignId);
            if (afterCommit.ChangedCampaign is Guid changedCampaignId)
                await cache.InvalidateCampaignAsync(changedCampaignId, ct);   // CMP-09: RaisedAmount تغيّر

            return Result.Success();
        }
    }

    private AfterCommit LogUnhandled(PaymentWebhookEvent evt)
    {
        logger.LogInformation("Unhandled Stripe event type {EventType} ({EventId})", evt.Type, evt.EventId);
        return AfterCommit.Nothing;
    }
}

// تابع داخل نفس الكلاس ProcessStripeWebhookCommandHandler (الكلاس ليس partial)

    private async Task<AfterCommit> HandleCompletedAsync(PaymentWebhookEvent evt, DateTime now, CancellationToken ct)
    {
        var attempt = evt.CheckoutSessionId is null ? null
            : await payments.GetAttemptBySessionIdAsync(evt.CheckoutSessionId, ct);

        if (attempt is null
            || !Guid.TryParse(evt.ClientReferenceId, out var donationId)
            || attempt.DonationId != donationId)
        {
            logger.LogWarning("Stripe event {EventId}: unknown checkout session {SessionId}", evt.EventId, evt.CheckoutSessionId);
            return AfterCommit.Nothing;
        }

        var donation = await uow.Repository<Donation>().GetByIdAsync(donationId, ct);
        var campaign = donation is null ? null : await uow.Repository<Campaign>().GetByIdAsync(donation.CampaignId, ct);
        if (donation is null || campaign is null)
        {
            logger.LogError("Stripe event {EventId}: donation {DonationId} or its campaign was not found", evt.EventId, donationId);
            return AfterCommit.Nothing;
        }

        if (evt.PaymentStatus != "paid")
        {
            logger.LogWarning("Checkout session {SessionId} completed with payment status {PaymentStatus}",
                evt.CheckoutSessionId, evt.PaymentStatus);
            return AfterCommit.Nothing;
        }

        // PAY-07: المرجع هو قاعدة البيانات، لا ما يقوله الحدث
        var expectedMinor = MinorUnits.FromAmount(donation.Amount, gateway.Currency);
        if (evt.AmountTotalMinor != expectedMinor
            || !string.Equals(evt.Currency, gateway.Currency, StringComparison.OrdinalIgnoreCase))
        {
            logger.LogError(
                "Payment mismatch for donation {DonationId}: paid {PaidMinor} {PaidCurrency}, expected {ExpectedMinor} {ExpectedCurrency}",
                donation.Id, evt.AmountTotalMinor, evt.Currency, expectedMinor, gateway.Currency);
            return AfterCommit.Nothing;   // التبرع يبقى Pending
        }

        if (donation.Status != DonationStatus.Pending)
        {
            if (donation.Status == DonationStatus.Failed)
                logger.LogError("Donation {DonationId} was paid after it failed; a manual refund is required", donation.Id);
            else
                logger.LogWarning("Donation {DonationId} already succeeded; extra session {SessionId} was paid",
                    donation.Id, evt.CheckoutSessionId);

            if (attempt.Status != PaymentAttemptStatus.Succeeded)
                attempt.MarkSucceeded(evt.PaymentIntentId, now);   // نسجّل أن المال وصل فعلًا
            return AfterCommit.Nothing;
        }

        // SRS §5.5: الدفعة المتأخرة تُقبل، مع تحذير
        if (campaign.Status != CampaignStatus.Active || campaign.EndDate <= now)
            logger.LogWarning("Late payment accepted for donation {DonationId} on campaign {CampaignId} ({CampaignStatus})",
                donation.Id, campaign.Id, campaign.Status);

        var wasCompleted = campaign.Status == CampaignStatus.Completed;
        _receiptNumber ??= await receiptNumbers.NextAsync(now, ct);   // DN-{year}-{000001}

        donation.MarkSucceeded(campaign, _receiptNumber, now);   // Succeeded + CompletedAt + RaisedAmount + Completed
        attempt.MarkSucceeded(evt.PaymentIntentId, now);

        logger.LogInformation("Donation {DonationId} succeeded via Stripe event {EventId}", donation.Id, evt.EventId);

        var justCompleted = !wasCompleted && campaign.Status == CampaignStatus.Completed;
        return new AfterCommit(donation.Id, justCompleted ? campaign.Id : null, campaign.Id);
    }

// تابع داخل نفس الكلاس ProcessStripeWebhookCommandHandler (الكلاس ليس partial)

    private async Task<AfterCommit> HandleExpiredAsync(PaymentWebhookEvent evt, DateTime now, CancellationToken ct)
    {
        var attempt = evt.CheckoutSessionId is null ? null
            : await payments.GetAttemptBySessionIdAsync(evt.CheckoutSessionId, ct);

        if (attempt is null)
            logger.LogWarning("Stripe event {EventId}: unknown expired session {SessionId}", evt.EventId, evt.CheckoutSessionId);
        else if (attempt.IsOpen)
            attempt.MarkExpired(now);   // التبرع يبقى Pending: يمكن فتح جلسة جديدة

        return AfterCommit.Nothing;
    }

    private async Task<AfterCommit> HandleFailedAsync(PaymentWebhookEvent evt, DateTime now, CancellationToken ct)
    {
        PaymentAttempt? attempt = null;
        if (Guid.TryParse(evt.PaymentAttemptId, out var attemptId))
            attempt = await uow.Repository<PaymentAttempt>().GetByIdAsync(attemptId, ct);
        if (attempt is null && evt.PaymentIntentId is not null)
            attempt = await payments.GetAttemptByPaymentIntentIdAsync(evt.PaymentIntentId, ct);

        if (attempt is null || !attempt.IsOpen)
        {
            logger.LogWarning("Stripe event {EventId}: no open attempt for payment intent {PaymentIntentId}",
                evt.EventId, evt.PaymentIntentId);
            return AfterCommit.Nothing;
        }

        attempt.MarkFailed(evt.FailureCode ?? "payment_failed", evt.PaymentIntentId, now);

        if (!await payments.HasOtherOpenAttemptsAsync(attempt.DonationId, attempt.Id, ct))
        {
            var donation = await uow.Repository<Donation>().GetByIdAsync(attempt.DonationId, ct);
            if (donation is { Status: DonationStatus.Pending })
                donation.MarkFailed($"Payment failed: {attempt.FailureCode}", now);
        }

        logger.LogInformation("Payment attempt {AttemptId} failed with {FailureCode}", attempt.Id, attempt.FailureCode);
        return AfterCommit.Nothing;
    }

