using DonationHub.Application.Abstractions;
using DonationHub.Domain.Idempotency;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;

namespace DonationHub.Infrastructure.Persistence;

internal sealed class EfIdempotencyStore(AppDbContext db) : IIdempotencyStore
{
    public async Task<IdempotencyBeginResult> TryBeginAsync(string key, Guid userId, string requestHash,
        DateTime utcNow, DateTime expiresAt, CancellationToken ct)
    {
        // مفتاح أقدم من 24 ساعة يُعامل كمفتاح جديد
        await db.IdempotencyRecords
            .Where(r => r.Key == key && r.UserId == userId && r.ExpiresAt <= utcNow)
            .ExecuteDeleteAsync(ct);

        var record = IdempotencyRecord.Start(key, userId, requestHash, utcNow, expiresAt);
        db.IdempotencyRecords.Add(record);
        try
        {
            await db.SaveChangesAsync(ct);
            return new IdempotencyBeginResult(IdempotencyOutcome.Started);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqlException { Number: 2627 or 2601 })
        {
            // المفتاح موجود — نحدد نوع التكرار بالأسفل
        }
        finally
        {
            db.Entry(record).State = EntityState.Detached;
        }

        var existing = await db.IdempotencyRecords.AsNoTracking()
            .FirstOrDefaultAsync(r => r.Key == key && r.UserId == userId, ct);

        if (existing is null)
            return new IdempotencyBeginResult(IdempotencyOutcome.InProgress);   // حُرّر للتو؛ العميل يعيد المحاولة
        if (existing.RequestHash != requestHash)
            return new IdempotencyBeginResult(IdempotencyOutcome.Mismatch);
        if (existing.ResponseStatusCode == IdempotencyRecord.InProgress)
            return new IdempotencyBeginResult(IdempotencyOutcome.InProgress);

        return new IdempotencyBeginResult(IdempotencyOutcome.Replay, existing.ResponseStatusCode, existing.ResponseBody);
    }

    public Task CompleteAsync(string key, Guid userId, int statusCode, string responseBody, CancellationToken ct) =>
        db.IdempotencyRecords
            .Where(r => r.Key == key && r.UserId == userId)
            .ExecuteUpdateAsync(s => s
                .SetProperty(r => r.ResponseStatusCode, statusCode)
                .SetProperty(r => r.ResponseBody, responseBody), ct);

    public Task ReleaseAsync(string key, Guid userId, CancellationToken ct) =>
        db.IdempotencyRecords
            .Where(r => r.Key == key && r.UserId == userId)
            .ExecuteDeleteAsync(ct);
}

