public sealed class IdempotentAttribute : TypeFilterAttribute
{
    public IdempotentAttribute() : base(typeof(IdempotencyFilter)) { }
}

internal sealed class IdempotencyFilter(
    IIdempotencyStore store,
    TimeProvider timeProvider,
    IOptions<Microsoft.AspNetCore.Mvc.JsonOptions> jsonOptions) : IAsyncActionFilter   // مؤهَّل بالكامل: يوجد JsonOptions آخر في Microsoft.AspNetCore.Http.Json
{
    public const string HeaderName = "Idempotency-Key";
    private static readonly TimeSpan Lifetime = TimeSpan.FromHours(24);

    public async Task OnActionExecutionAsync(ActionExecutingContext context, ActionExecutionDelegate next)
    {
        var http = context.HttpContext;
        var key = http.Request.Headers[HeaderName].ToString();
        if (string.IsNullOrWhiteSpace(key) || key.Length > 100)
        {
            context.Result = Problem(http, IdempotencyErrors.KeyMissing);
            return;
        }

        var userId = http.User.GetUserId();
        var requestHash = ComputeHash(http.Request.Path, context.ActionArguments);
        var now = timeProvider.GetUtcNow().UtcDateTime;

        var begin = await store.TryBeginAsync(key, userId, requestHash, now, now.Add(Lifetime), http.RequestAborted);
        switch (begin.Outcome)
        {
            case IdempotencyOutcome.Mismatch:
                context.Result = Problem(http, IdempotencyErrors.KeyReusedWithDifferentRequest);
                return;
            case IdempotencyOutcome.InProgress:
                context.Result = Problem(http, IdempotencyErrors.RequestInProgress);
                return;
            case IdempotencyOutcome.Replay:
                http.Response.Headers["Idempotent-Replayed"] = "true";
                context.Result = new ContentResult
                {
                    StatusCode = begin.StatusCode,
                    Content = begin.Body,
                    ContentType = begin.StatusCode >= 400 ? "application/problem+json" : "application/json; charset=utf-8"
                };
                return;
        }

        var executed = await next();

        if (executed.Exception is null && executed.Result is ObjectResult result)
        {
            var status = result.StatusCode ?? StatusCodes.Status200OK;
            if (status < 500)
            {
                var body = JsonSerializer.Serialize(result.Value, result.Value?.GetType() ?? typeof(object),
                    jsonOptions.Value.JsonSerializerOptions);
                await store.CompleteAsync(key, userId, status, body, CancellationToken.None);
                return;
            }
        }

        // استثناء أو 5xx: لا نحفظ نتيجة غير مكتملة — نحرّر المفتاح
        await store.ReleaseAsync(key, userId, CancellationToken.None);
    }

    private string ComputeHash(PathString path, IDictionary<string, object?> arguments)
    {
        var relevant = arguments
            .Where(a => a.Value is not CancellationToken)
            .OrderBy(a => a.Key, StringComparer.Ordinal)
            .ToDictionary(a => a.Key, a => a.Value);

        var json = JsonSerializer.Serialize(new { path = path.Value, args = relevant }, jsonOptions.Value.JsonSerializerOptions);
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(json)));
    }

    // نفس شكل ApiControllerBase.ProblemFrom (Sprint 2) — الفلتر ليس controller فلا يرثه
    private static ObjectResult Problem(HttpContext http, Error error)
    {
        var status = error.Type.ToStatusCode();   // ErrorTypeExtensions من Sprint 2

        var problem = new ProblemDetails { Status = status, Title = error.Message, Type = $"https://httpstatuses.io/{status}" };
        problem.Extensions["code"] = error.Code;
        problem.Extensions["traceId"] = Activity.Current?.Id ?? http.TraceIdentifier;
        if (error.Type == ErrorType.Validation)
            problem.Extensions["errors"] = new Dictionary<string, string[]> { [HeaderName] = [error.Message] };

        return new ObjectResult(problem) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

