    // السيناريو 2 + الرحلة الحرجة حتى ما قبل الـ webhook
    private async Task<Arranged> ArrangePendingDonationAsync(decimal amount)
    {
        var admin = factory.CreateClient();
        admin.UseToken(await admin.LoginAsync(DonationHubApiFactory.AdminEmail, DonationHubApiFactory.AdminPassword));
        var campaignId = await admin.CreateCampaignAsAdminAsync(goal: 1000m);

        var donor = factory.CreateClient();
        donor.UseToken(await donor.RegisterAndLoginAsync($"donor-{Guid.NewGuid():N}@tests.local"));

        var created = await donor.CreateDonationAsync(campaignId, amount, Guid.NewGuid().ToString());
        created.StatusCode.Should().Be(HttpStatusCode.Created);
        var donation = await created.Content.ReadFromJsonAsync<JsonElement>();
        donation.GetProperty("status").GetString().Should().Be("Pending");
        var donationId = donation.GetProperty("id").GetGuid();

        var checkout = await donor.CheckoutAsync(donationId);
        checkout.StatusCode.Should().Be(HttpStatusCode.OK);
        var sessionId = (await checkout.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("sessionId").GetString()!;

        return new Arranged(donor, campaignId, donationId, sessionId);
    }

    [Fact]   // السيناريو 3
    public async Task Signed_checkout_completed_marks_donation_succeeded_and_updates_raised_amount()
    {
        var a = await ArrangePendingDonationAsync(25.00m);
        var payload = StripeWebhookSigner.CheckoutSessionCompleted($"evt_{Guid.NewGuid():N}", a.SessionId, a.DonationId, 2500);

        var response = await a.Donor.PostWebhookAsync(payload, StripeWebhookSigner.Sign(payload, DonationHubApiFactory.WebhookSecret));

        response.StatusCode.Should().Be(HttpStatusCode.OK);
        var donation = await factory.QueryDbAsync(db => db.Donations.AsNoTracking().SingleAsync(d => d.Id == a.DonationId));
        donation.Status.Should().Be(DonationStatus.Succeeded);
        donation.ReceiptNumber.Should().MatchRegex(@"^DN-\d{4}-\d{6}$");
        var campaign = await factory.QueryDbAsync(db => db.Campaigns.AsNoTracking().SingleAsync(c => c.Id == a.CampaignId));
        campaign.RaisedAmount.Should().Be(25.00m);
        factory.Jobs.Receipts.Should().Contain(a.DonationId);   // أُضيف للطابور بعد الـ commit
    }

    [Fact]   // السيناريو 4
    public async Task Duplicate_event_is_acknowledged_and_credited_once()
    {
        var a = await ArrangePendingDonationAsync(40.00m);
        var eventId = $"evt_{Guid.NewGuid():N}";
        var payload = StripeWebhookSigner.CheckoutSessionCompleted(eventId, a.SessionId, a.DonationId, 4000);
        var signature = StripeWebhookSigner.Sign(payload, DonationHubApiFactory.WebhookSecret);

        var first = await a.Donor.PostWebhookAsync(payload, signature);
        var second = await a.Donor.PostWebhookAsync(payload, signature);

        first.StatusCode.Should().Be(HttpStatusCode.OK);
        second.StatusCode.Should().Be(HttpStatusCode.OK);
        var campaign = await factory.QueryDbAsync(db => db.Campaigns.AsNoTracking().SingleAsync(c => c.Id == a.CampaignId));
        campaign.RaisedAmount.Should().Be(40.00m);
        var processed = await factory.QueryDbAsync(db => db.ProcessedStripeEvents.CountAsync(e => e.EventId == eventId));
        processed.Should().Be(1);
    }

    [Fact]   // السيناريو 5
    public async Task Invalid_signature_returns_400_and_changes_nothing()
    {
        var a = await ArrangePendingDonationAsync(30.00m);
        var payload = StripeWebhookSigner.CheckoutSessionCompleted($"evt_{Guid.NewGuid():N}", a.SessionId, a.DonationId, 3000);

        var response = await a.Donor.PostWebhookAsync(payload, StripeWebhookSigner.Sign(payload, "whsec_wrong_secret"));

        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);
        var problem = await response.Content.ReadFromJsonAsync<JsonElement>();
        problem.GetProperty("code").GetString().Should().Be("Payment.InvalidSignature");
        var donation = await factory.QueryDbAsync(db => db.Donations.AsNoTracking().SingleAsync(d => d.Id == a.DonationId));
        donation.Status.Should().Be(DonationStatus.Pending);
        var campaign = await factory.QueryDbAsync(db => db.Campaigns.AsNoTracking().SingleAsync(c => c.Id == a.CampaignId));
        campaign.RaisedAmount.Should().Be(0m);
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using DonationHub.Api.IntegrationTests.Infrastructure;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;

namespace DonationHub.Api.IntegrationTests;

[Collection(ApiCollection.Name)]
public sealed class IdempotencyTests(DonationHubApiFactory factory)
{
    private async Task<(HttpClient Donor, Guid CampaignId)> ArrangeAsync()
    {
        var admin = factory.CreateClient();
        admin.UseToken(await admin.LoginAsync(DonationHubApiFactory.AdminEmail, DonationHubApiFactory.AdminPassword));
        var campaignId = await admin.CreateCampaignAsAdminAsync();

        var donor = factory.CreateClient();
        donor.UseToken(await donor.RegisterAndLoginAsync($"donor-{Guid.NewGuid():N}@tests.local"));
        return (donor, campaignId);
    }

    [Fact]   // السيناريو 6
    public async Task Same_key_and_body_returns_stored_response_without_a_second_donation()
    {
        var (donor, campaignId) = await ArrangeAsync();
        var key = Guid.NewGuid().ToString();

        var first = await donor.CreateDonationAsync(campaignId, 25.00m, key);
        var replay = await donor.CreateDonationAsync(campaignId, 25.00m, key);

        first.StatusCode.Should().Be(HttpStatusCode.Created);
        replay.StatusCode.Should().Be(HttpStatusCode.Created);
        var firstId = (await first.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
        var replayId = (await replay.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
        replayId.Should().Be(firstId);

        var count = await factory.QueryDbAsync(db => db.Donations.CountAsync(d => d.CampaignId == campaignId));
        count.Should().Be(1);
    }

    [Fact]
    public async Task Same_key_with_different_body_returns_422()
    {
        var (donor, campaignId) = await ArrangeAsync();
        var key = Guid.NewGuid().ToString();

        await donor.CreateDonationAsync(campaignId, 25.00m, key);
        var reused = await donor.CreateDonationAsync(campaignId, 50.00m, key);

        reused.StatusCode.Should().Be(HttpStatusCode.UnprocessableEntity);
        var problem = await reused.Content.ReadFromJsonAsync<JsonElement>();
        problem.GetProperty("code").GetString().Should().Be("Idempotency.KeyReusedWithDifferentRequest");
    }

}

public async Task RefundAsync(string paymentIntentId, string idempotencyKey, CancellationToken ct)
{
    var service = new RefundService(stripeClient);
    await service.CreateAsync(
        new RefundCreateOptions { PaymentIntent = paymentIntentId },
        new RequestOptions { IdempotencyKey = idempotencyKey },
        ct);
